INSERT INTO `lang_mgr` VALUES (125, 'rech_minamount', '最小充值金额为', 'The minimum recharge amount is', '最小儲值金額為', 'Der Mindestaufladebetrag beträgt', 'El importe mínimo de recarga es', 'Le montant minimum de recharge est', 'Jumlah isi ulang minimum adalah', '最低チャージ金額は、', '최소 충전금액은', 'Jumlah cas semula minimum ialah', 'จำนวนเงินเติมเงินขั้นต่ำคือ', 'Số tiền nạp tối thiểu là', 'valor mínimo de recarga é', 'Минимальная сумма пополнения составляет', 'Мінімальная сума папаўнення складае', 'न्यूनतम रिचार्ज राशि है', 'الحد الأدنى لمبلغ إعادة الشحن هو', 'الحد الأدنى لمبلغ إعادة الشحن هو', 'L\'importo minimo di ricarica è', '');
