kAutoFrom&quot;:null},{&quot;AmpSrc&quot;:&quot;https://av.voanews.com/Videoroot/Pangeavideo/2024/03/0/01/01000000-0aff-0242-fb01-08dc4a9b7ff1_480p.mp4&quot;,&quot;Src&quot;:&quot;https://av.voanews.com/Videoroot/Pangeavideo/2024/03/0/01/01000000-0aff-0242-fb01-08dc4a9b7ff1_480p.mp4&quot;,&quot;Type&quot;:&quot;video/mp4&quot;,&quot;DataInfo&quot;:&quot;480p&quot;,&quot;Url&quot;:null,&quot;BlockAutoTo&quot;:null,&quot;BlockAutoFrom&quot;:null},{&quot;AmpSrc&quot;:&quot;https://av.voanews.com/Videoroot/Pangeavideo/2024/03/0/01/01000000-0aff-0242-fb01-08dc4a9b7ff1_720p.mp4&quot;,&quot;Src&quot;:&quot;https://av.voanews.com/Videoroot/Pangeavideo/2024/03/0/01/01000000-0aff-0242-fb01-08dc4a9b7ff1_720p.mp4&quot;,&quot;Type&quot;:&quot;video/mp4&quot;,&quot;DataInfo&quot;:&quot;540p&quot;,&quot;Url&quot;:null,&quot;BlockAutoTo&quot;:null,&quot;BlockAutoFrom&quot;:null}]\" data-lt-on-play=\"0\" data-lt-url=\"\" webkit-playsinline=\"webkit-playsinline\" playsinline=\"playsinline\" style=\"width:100%\" title=\"Au Sénégal, Après des semaines de tensions, le peuple uni pour un vote historique\" data-sdkadaptive=\"true\" data-sdkamp=\"false\" data-sdktitle=\"Au Sénégal, Après des semaines de tensions, le peuple uni pour un vote historique\" data-sdkvideo=\"html5\" data-sdkid=\"7538867\" data-sdktype=\"Video ondemand\"> \n      </video> \n     </div> \n     <div class=\"c-mmp__overlay c-mmp__overlay--title c-mmp__overlay--partial c-mmp__overlay--disabled c-mmp__overlay--slide-from-top js-c-mmp__title-overlay\"> <span class=\"c-mmp__overlay-actions c-mmp__overlay-actions-top js-overlay-actions\"> <span class=\"c-mmp__overlay-actions-link c-mmp__overlay-actions-link--embed js-btn-embed-overlay\" title=\"Embed\"> <span class=\"c-mmp__overlay-actions-link-ico ico ico-embed-code\"></span> <span class=\"c-mmp__overlay-actions-link-text\">Embed</span> </span> <span class=\"c-mmp__overlay-actions-link c-mmp__overlay-actions-link--share js-btn-sharing-overlay\" title=\"share\"> <span cla