-- ----------------------------
-- Table structure for app_config
-- ----------------------------
DROP TABLE IF EXISTS `app_config`;
CREATE TABLE `app_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `page_path` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '页面路径',
  `desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '介绍',
  `module` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模块',
  `img_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '图片路径',
  `hint_txt` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '提示文本',
  `view_type` tinyint(1) NULL DEFAULT NULL COMMENT '视图类型 0：图片1：输入框2：纯文本3：按钮',
  `is_visible` bit(1) NULL DEFAULT b'1' COMMENT '是否显示 0：否 1：是',
  `is_require` bit(1) NULL DEFAULT b'1' COMMENT '是否必填 0：否 1：是',
  `is_password` bit(1) NULL DEFAULT b'1' COMMENT '是否密码 0：否 1：是',
  `pattern_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '规则类型',
  `call_fun` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '调用方法',
  `obj_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '显示文本及输入用',
  `obj_property_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'obj_字段名',
  `sort` int NULL DEFAULT NULL COMMENT '排序',
  `str_right` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '右边按键文本，可控制隐藏（举例：快捷复制按钮）',
  `client_version` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客户端版本',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `page_path`(`page_path`) USING BTREE,
  INDEX `client_version`(`client_version`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 241 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'app配置' ROW_FORMAT = DYNAMIC;

