-- ----------------------------
DROP TABLE IF EXISTS `currency_exchange_rate`;
CREATE TABLE `currency_exchange_rate`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `currency_id_from` bigint NOT NULL COMMENT '转化者货币id',
  `currency_id_to` bigint NOT NULL COMMENT '被转化者货币id',
  `exchange_rate` decimal(22, 6) NOT NULL COMMENT '汇率',
  `opposite_exchange_rate` decimal(22, 6) NOT NULL COMMENT '反汇率',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `fee_percent` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '手续费率',
  `is_fixed_exchange_rate` tinyint(1) NULL DEFAULT 1 COMMENT '是否固定汇率 0:固定汇率   1:实时汇率',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `from`(`currency_id_from`, `currency_id_to`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8 COLLATE = utf8_unicode_ci COMMENT = '货币兑换汇率表' ROW_FORMAT = DYNAMIC;

