-- ----------------------------
-- Table structure for fast_order_control_config
-- ----------------------------
DROP TABLE IF EXISTS `fast_order_control_config`;
CREATE TABLE `fast_order_control_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `product_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '产品代码',
  `product_type` tinyint(1) NOT NULL COMMENT '产品类型（1：美股 2：加密货币）',
  `begin_time` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '开始时间',
  `finish_time` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '结束时间',
  `trade_direct` tinyint(1) NULL DEFAULT NULL COMMENT '交易方向 0：做多 1：做空',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态：0：启用 1：禁用',
  `win_or_lose` tinyint(1) NULL DEFAULT NULL COMMENT '输赢 0：输  1：赢 2：平 3:未控',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `product_type`(`product_type`, `product_code`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_unicode_ci COMMENT = '极速交易控制配置表' ROW_FORMAT = DYNAMIC;

