-- ----------------------------
-- Table structure for fast_trade_order
-- ----------------------------
DROP TABLE IF EXISTS `fast_trade_order`;
CREATE TABLE `fast_trade_order`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `product_type` tinyint(1) NOT NULL COMMENT '产品类型 （1：股票 2：加密货币 3：期货 4：外汇）',
  `order_code` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单编号',
  `user_id` bigint NOT NULL COMMENT '用户id',
  `product_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '产品代码',
  `product_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '产品名称',
  `order_direction` tinyint(1) NOT NULL COMMENT '交易方向0：涨 1：跌',
  `order_price` decimal(22, 6) NOT NULL COMMENT '下单金额',
  `handing_fee` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '手续费',
  `order_time` datetime(0) NULL DEFAULT NULL COMMENT '下单时间',
  `fast_trade_order_options_id` bigint NOT NULL COMMENT '极速交易选项id',
  `duration_value` int NOT NULL COMMENT '订单时长',
  `duration_label` tinyint(1) NOT NULL COMMENT '时长标签（0:秒 1：分钟 2：小时）',
  `profit_ratio` decimal(22, 6) NOT NULL COMMENT '收益比率',
  `buy_price` decimal(22, 6) NOT NULL COMMENT '买入价格',
  `sell_price` decimal(22, 6) NULL DEFAULT NULL COMMENT '结算价格',
  `order_status` tinyint(1) NULL DEFAULT 0 COMMENT '订单状态 0：待结算 1：已结算',
  `deliver_time` datetime(0) NOT NULL COMMENT '结算时间',
  `order_profit` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '订单收益',
  `currency_id` bigint NOT NULL DEFAULT 1 COMMENT '货币id',
  `lose_money_method` tinyint(1) NULL DEFAULT 0 COMMENT '输钱方式：0:全部扣除 1：按收益率扣除',
  `order_control_flag` tinyint(1) NULL DEFAULT 0 COMMENT '订单单控状态：0：未控  1：赢  2：输 3：平',
  `sql_version` bigint NULL DEFAULT 0 COMMENT 'sql版本',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `id`(`id`, `sql_version`) USING BTREE,
  INDEX `prudct_type`(`product_type`, `user_id`) USING BTREE,
  INDEX `product_code`(`product_code`) USING BTREE,
  INDEX `product_type`(`product_type`, `order_status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_unicode_ci COMMENT = '极速交易订单' ROW_FORMAT = DYNAMIC;

