-- Records of fast_trade_order
-- ----------------------------

-- ----------------------------
-- Table structure for fast_trade_order_options
-- ----------------------------
DROP TABLE IF EXISTS `fast_trade_order_options`;
CREATE TABLE `fast_trade_order_options`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `product_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '产品名称',
  `product_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '产品代码',
  `product_type` tinyint(1) NOT NULL COMMENT '产品类型（1：美股 2：加密货币 3:期货 4：外汇）',
  `duration_value` int NOT NULL COMMENT '时长',
  `duration_label` tinyint(1) NOT NULL COMMENT '时长标签（0:秒 1：分钟 2：小时）',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态: 0启用 1停用',
  `up_profit_ratio` decimal(22, 6) NOT NULL COMMENT '涨收益率',
  `up_fluctuation_ratio` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '涨波动率',
  `down_profit_ratio` decimal(22, 6) NOT NULL COMMENT '跌收益率',
  `down_fluctuation_ratio` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '跌波动率',
  `min_buy_amount` decimal(22, 6) NOT NULL COMMENT '最小买入金额',
  `max_buy_amount` decimal(22, 6) NULL DEFAULT NULL COMMENT '最大买入金额',
  `vip_level_limit` varchar(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT 'vip等级限制',
  `min_user_amount` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '用户金额大于此刻度可下单',
  `profit_ratio_method` tinyint(1) NULL DEFAULT 0 COMMENT '收益率方式 0:固定   1:波动',
  `lose_money_method` tinyint(1) NULL DEFAULT 0 COMMENT '输钱方式：0:全部扣除 1：按收益率扣除',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `stock_code`(`product_code`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_unicode_ci COMMENT = '极速交易下单选项表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of fast_trade_order_options
-- ----------------------------

-- ----------------------------
-- Table structure for financial_order
-- ----------------------------
DROP TABLE IF EXISTS `financial_order`;
CREATE TABLE `financial_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `financial_product_id` bigint NULL DEFAULT NULL COMMENT '理财产品id',
  `financial_time` int NULL DEFAULT 1 COMMENT '理财天数',
  `buy_price` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '理财购买金额',
  `interest_time` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '派息天数',
  `user_id` bigint NULL DEFAULT NULL COMMENT '用户id',
  `start_date` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '理财开始日期',
  `end_date` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '理财结束日期',
  `last_interest_time` datetime(0) NULL DEFAULT NULL COMMENT '最后派息时间',
  `already_interest_count` int NULL DEFAULT 0 COMMENT '已经派息次数',
  `break_contract_rate` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '违约金比率',
  `daily_income_rate` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '日收益率',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '下单时间',
  `order_status` tinyint(1) NULL DEFAULT 0 COMMENT '订单状态：0：待审核  1：进行中 2：已完成 3：已驳回',
  `auto_renew` tinyint(1) NULL DEFAULT 1 COMMENT '是否自动续约 0：是 1：否',
  `currency_id` bigint NOT NULL DEFAULT 3 COMMENT '货币id',
  `float_daily_income_min_rate` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '浮动日收益最低',
  `float_daily_income_max_rate` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '浮动日收益最高',
  `sql_version` bigint NULL DEFAULT 0 COMMENT 'sql版本',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `id`(`id`, `sql_version`) USING BTREE,
  INDEX `user_id`(`user_id`) USING BTREE,
  INDEX `order_status`(`order_status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_unicode_ci COMMENT = '理财订单' ROW_FORMAT = DYNAMIC;

