  `listing_day_increase_rate` decimal(22, 6) NOT NULL DEFAULT 0.000000 COMMENT '上市当天涨幅率',
  `user_amount_limit` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '用户余额最低要求',
  `trade_date` datetime(0) NULL DEFAULT NULL COMMENT '交易日期',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态0：启用 1：禁用',
  `sort` int NULL DEFAULT NULL COMMENT '排序',
  `apply_purchase_start_date` datetime(0) NOT NULL COMMENT '申购开始日期',
  `apply_purchase_end_date` datetime(0) NOT NULL COMMENT '申购结束日期',
  `remaining_quantity` int NULL DEFAULT 0 COMMENT '剩余数量',
  `listing_start_date` datetime(0) NOT NULL COMMENT '上市开始日期',
  `listing_end_date` datetime(0) NOT NULL COMMENT '上市结束日期',
  `listed_day_increase_rate` decimal(22, 6) NOT NULL DEFAULT 0.000000 COMMENT '上市后每天涨幅率',
  `apply_purchase_min` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '单笔申购金额最低',
  `apply_purchase_max` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '单笔申购金额最高',
  `lockup_period` int NULL DEFAULT 0 COMMENT '锁仓期限',
  `listing_status` tinyint(1) NULL DEFAULT 0 COMMENT '上市状态：0：预申购 1：正在申购 2：已上市',
  `product_type` tinyint(1) NULL DEFAULT 1 COMMENT '产品类型 1：股票 2：加密货币',
  `sql_version` bigint NULL DEFAULT 0 COMMENT 'sql版本',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `stock_status`(`listing_status`, `status`, `listing_start_date`, `apply_purchase_start_date`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_unicode_ci COMMENT = '新股申购初始配置表' ROW_FORMAT = DYNAMIC;

