-- ----------------------------
-- Table structure for product_quote_control
-- ----------------------------
DROP TABLE IF EXISTS `product_quote_control`;
CREATE TABLE `product_quote_control`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `product_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '产品代码',
  `product_type` tinyint(1) NOT NULL COMMENT '产品类型 1：股票 2：加密货币 3：期货 4：外汇',
  `preset_price` decimal(22, 6) NOT NULL COMMENT '预设点位',
  `preset_start_time` datetime(0) NOT NULL COMMENT '启动时间',
  `preset_duration` int NOT NULL COMMENT '预设时长',
  `return_duration` int NOT NULL COMMENT '回归时长',
  `arrive_preset_price_time` datetime(0) NOT NULL COMMENT '到达预设点位时间',
  `preset_end_time` datetime(0) NOT NULL COMMENT '预设结束时间',
  `start_price` decimal(22, 6) NULL DEFAULT NULL COMMENT '启动点位',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态：0：已预设 1：已启动',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `product_code`(`product_code`, `product_type`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '产品短线行情控制' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of product_quote_control
-- ----------------------------

-- ----------------------------
-- Table structure for product_setting
-- ----------------------------
DROP TABLE IF EXISTS `product_setting`;
CREATE TABLE `product_setting`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `duty_fee` decimal(22, 6) NULL DEFAULT 0.001000 COMMENT '印花税率',
  `stay_fee` decimal(22, 6) NULL DEFAULT 0.001000 COMMENT '留仓费率',
  `stay_max_days` int NULL DEFAULT 15 COMMENT '最大留仓天数',
  `buy_min_amt` decimal(22, 6) NULL DEFAULT 1.000000 COMMENT '最小购买金额',
  `buy_min_num` int NULL DEFAULT 1 COMMENT '最小购买数量',
  `buy_max_num` int NULL DEFAULT 1000000 COMMENT '最大购买数量',
  `buy_max_amt_percent` decimal(22, 6) NULL DEFAULT 1.000000 COMMENT '最大买入比例',
  `force_stop_percent` decimal(22, 6) NULL DEFAULT 0.990000 COMMENT '强制平仓比例',
  `site_lever` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '100/10/8/5/1' COMMENT '快捷交易杠杆倍数,多个用/分割',
  `hand_num` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '50/100/150/200' COMMENT '快捷交易手数',
  `buy_same_times` int NULL DEFAULT NULL COMMENT 'N分钟内同一只股票不得下单M次（N）',
  `buy_same_nums` int NULL DEFAULT NULL COMMENT 'N分钟内同一只股票不得下单M次（M）',
  `buy_num_times` int NULL DEFAULT NULL COMMENT 'N分钟内交易手数不能超过M次（N）',
  `buy_num_lots` int NULL DEFAULT NULL COMMENT 'N分钟内交易手数不能超过M次（M）',
  `cant_sell_times` int NULL DEFAULT 3 COMMENT '至少持有时间（分钟）',
  `hand_correspond_num` int NULL DEFAULT 100 COMMENT '一手对应的数量',
  `liquidation_method` tinyint(1) NULL DEFAULT 1 COMMENT '爆仓模式 1:保证金+账户余额亏完 2:保证金亏完 3:全亏损',
  `product_type` tinyint(1) NULL DEFAULT NULL COMMENT '产品类型：1：股票 2：加密货币 3：期货 4：外汇',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `stock_type`(`product_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci COMMENT = '产品交易设置（产品风控）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of product_setting
-- ----------------------------

-- ----------------------------
-- Table structure for product_trade_time_setting
-- ----------------------------
DROP TABLE IF EXISTS `product_trade_time_setting`;
CREATE TABLE `product_trade_time_setting`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `day` tinyint(1) NOT NULL COMMENT '天(周一到周天，1~7)',
  `trans_am_begin` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '9:30' COMMENT '早上交易开始时间',
  `trans_am_end` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '11:30' COMMENT '早上交易结束时间',
  `trans_pm_begin` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '13:00' COMMENT '下午交易开始时间',
  `trans_pm_end` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '16:00' COMMENT '下午交易结束时间',
  `product_type` tinyint(1) NOT NULL COMMENT '产品类型：1美股，2加密货币 3外汇 4期货',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `day`(`day`, `product_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29 CHARACTER SET = utf8 COLLATE = utf8_unicode_ci COMMENT = '系统产品交易时间配置' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of product_trade_time_setting
-- ----------------------------

-- ----------------------------
-- Table structure for qrtz_blob_triggers
-- ----------------------------
