  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `product_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '产品代码',
  `time` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '时间(HH:mm)',
  `volumes` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '成交量',
  `price` decimal(22, 6) NOT NULL DEFAULT 0.000000 COMMENT '现价',
  `rates` decimal(22, 6) NOT NULL DEFAULT 0.000000 COMMENT '涨跌幅',
  `amounts` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '手数',
  `average_price` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '均价',
  `product_type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '类型：1：股票 2：加密货币 3：期货 4:外汇',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '加入时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `product_type`(`product_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 42089 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '产品分时图数据(模板)' ROW_FORMAT = DYNAMIC;

