-- ----------------------------
-- Table structure for scheduled_task_exception_log
-- ----------------------------
DROP TABLE IF EXISTS `scheduled_task_exception_log`;
CREATE TABLE `scheduled_task_exception_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务日志ID',
  `job_name` varchar(64) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '任务名称',
  `exception_info` varchar(2000) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT '异常信息',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '最后执行时间',
  `is_fixed` tinyint(1) NULL DEFAULT 0 COMMENT '是否修复 0：未修复 1：已修复 ',
  `exception_info_detail` longtext CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL COMMENT '异常详情',
  `type` int NOT NULL COMMENT '类型：1：理财派发利息任务 2：股票止盈止损触发定时任务 3：加密货币止盈止损触发定时任务 4：期货止盈止损触发定时任务 5:新股新币上市定时器 6:新股新币开始申购定时器 7:留仓费收取定时任务 8:股票留仓到期强制平仓任务 9:同步节假日开关定时任务 10:每日16点收盘时保存每日数据定时任务  11:删除分时图数据定时任务\r\n12：外汇止盈止损定时任务 13:股票强制平仓定时任务 14：加密货币强制平仓定时任务 15：期货强制平仓定时任务 16：外汇强制平仓定时任务',
  `execute_count` int NULL DEFAULT 1 COMMENT '执行次数',
  `relate_info` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '相关信息 （id或订单号等）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `is_fixed`(`is_fixed`, `type`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_unicode_ci COMMENT = '定时任务异常日志' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of scheduled_task_exception_log
-- ----------------------------

