-- ----------------------------
-- Table structure for self_sell_product_daily_data_config
-- ----------------------------
DROP TABLE IF EXISTS `self_sell_product_daily_data_config`;
CREATE TABLE `self_sell_product_daily_data_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `self_sell_product_id` bigint NOT NULL COMMENT '自营产品id',
  `product_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '产品代码',
  `is_default` tinyint(1) NULL DEFAULT 1 COMMENT '是否默认：0：是 1：否',
  `finally_change_rate` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '设置的最终涨跌幅',
  `finally_price` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '设置的最终价格',
  `is_temp` tinyint(1) NULL DEFAULT 1 COMMENT '是否根据其他支的股票模板复刻数据0：是 1：否',
  `temp_product_code` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '模板股票代码',
  `product_type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '产品类型 1：股票 2：加密货币',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `self_sell_product_id`(`self_sell_product_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_unicode_ci COMMENT = '自营币每日行情数据配置' ROW_FORMAT = DYNAMIC;

