  `msg_content_rus` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '信息内容-俄语',
  `msg_content_blr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '信息内容-白俄罗斯',
  `msg_content_ida` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '信息内容-印度',
  `msg_content_sa` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '信息内容-沙特阿拉伯',
  `msg_content_ar` text CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL COMMENT '信息内容-阿拉伯',
  `msg_content_it` text CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL COMMENT '信息内容-意大利',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `user_id`(`user_id`, `is_visible`) USING BTREE,
  INDEX `is_private`(`is_private`, `user_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_unicode_ci COMMENT = '平台站内信发送记录' ROW_FORMAT = DYNAMIC;

