  `site_message_id` bigint NOT NULL COMMENT '站内信id',
  `user_id` bigint NOT NULL COMMENT '用户id',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `site_message_id`(`site_message_id`, `user_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '平台站内信已读记录' ROW_FORMAT = DYNAMIC;

