-- ----------------------------
-- Table structure for spot_trade_order
-- ----------------------------
DROP TABLE IF EXISTS `spot_trade_order`;
CREATE TABLE `spot_trade_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `product_type` tinyint(1) NOT NULL COMMENT '产品类型：1：美股 2：加密货币 3:期货 4：外汇',
  `order_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单编号',
  `user_id` bigint NOT NULL COMMENT '用户id',
  `product_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '产品代码',
  `product_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '产品名称',
  `buy_order_time` datetime(0) NOT NULL COMMENT '购买时间',
  `buy_order_price` decimal(22, 6) NOT NULL COMMENT '购买价格',
  `sell_order_time` datetime(0) NULL DEFAULT NULL COMMENT '卖出时间',
  `sell_order_price` decimal(22, 6) NULL DEFAULT NULL COMMENT '卖出价格',
  `order_num` decimal(22, 6) NOT NULL COMMENT '订单数量',
  `order_total_price` decimal(22, 6) NOT NULL COMMENT '订单总金额',
  `order_fee` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '手续费',
  `profit_and_lose` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '浮动盈亏',
  `all_profit_and_lose` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '总盈亏',
  `currency_id` bigint NOT NULL DEFAULT 1 COMMENT '币种id',
  `order_status` tinyint(1) NULL DEFAULT 0 COMMENT '状态0：未卖出 1：已卖出',
  `sql_version` bigint NULL DEFAULT 0 COMMENT 'sql版本',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `product_type`(`product_type`, `user_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '现货交易订单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of spot_trade_order
-- ----------------------------

-- ----------------------------
-- Table structure for stock_everyday_record
-- ----------------------------
DROP TABLE IF EXISTS `stock_everyday_record`;
CREATE TABLE `stock_everyday_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `product_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '产品代码',
  `now_price` decimal(22, 6) NOT NULL COMMENT '现价',
  `change_rate` decimal(22, 6) NOT NULL DEFAULT 0.000000 COMMENT '涨跌幅',
  `open_price` decimal(22, 6) NOT NULL COMMENT '开盘价',
  `close_price` decimal(22, 6) NOT NULL COMMENT '收盘价',
  `business_amount` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '交易总金额',
  `business_volume` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '交易总量',
  `max_price` decimal(22, 6) NOT NULL COMMENT '最高价',
  `min_price` decimal(22, 6) NOT NULL COMMENT '最低价',
  `create_time` datetime(0) NOT NULL COMMENT '新增时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `product_code`(`product_code`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '股票日涨幅记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of stock_everyday_record
-- ----------------------------

