-- ----------------------------
DROP TABLE IF EXISTS `switch_set`;
CREATE TABLE `switch_set`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `switch_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '开关名称',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '开关状态：0：开启 1：关闭',
