DROP TABLE IF EXISTS `text_lang`;
CREATE TABLE `text_lang`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `content` text CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '文本内容',
