  `content_type` int NULL DEFAULT NULL COMMENT '类型：0：App实名认证页面规格 1：App银行卡页面规则 2：App提现页面规格 3:App按天配资规则 4:App挖矿收益计算 5:App挖矿关于违约金 6:公司简介 7:开户须知 8:操盘须知 9:投资风险 10：产品细节 12：注册协议 13：推广规则 14：福利中心',
  `website_class` tinyint(1) NULL DEFAULT NULL COMMENT '官网类型:  null:公用 1：官网：2:官网B',
  `content_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文本内容-英文',
  `content_tc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文本内容-繁体',
  `content_de` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文本内容-德国',
  `content_es` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文本内容-西班牙',
  `content_fr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文本内容-法国',
  `content_idn` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文本内容-印度尼西亚',
  `content_jp` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文本内容-日本',
  `content_ko` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文本内容-韩国',
  `content_my` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文本内容-马来西亚',
  `content_th` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文本内容-泰国',
  `content_vi` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文本内容-越南',
  `content_pt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文本内容-葡萄牙',
  `content_rus` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文本内容-俄语',
  `content_blr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文本内容-白俄罗斯',
  `content_ida` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文本内容-印度',
  `content_sa` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文本内容-沙特阿拉伯',
  `content_ar` text CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL COMMENT '文本内容-阿拉伯',
  `content_it` text CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL COMMENT '文本内容-意大利',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `content_type`(`content_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '文本多语言' ROW_FORMAT = DYNAMIC;

