-- ----------------------------
-- Table structure for user_amount
-- ----------------------------
DROP TABLE IF EXISTS `user_amount`;
CREATE TABLE `user_amount`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `amount` decimal(22, 6) NOT NULL DEFAULT 0.000000 COMMENT '余额',
  `currency_id` bigint NOT NULL COMMENT '币种id',
  `user_id` bigint NOT NULL COMMENT '用户id',
  `frozen_amount` decimal(22, 6) NOT NULL DEFAULT 0.000000 COMMENT '冻结金额',
  `sql_version` bigint NULL DEFAULT 0 COMMENT 'sql版本',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `currency_id`(`user_id`, `currency_id`) USING BTREE,
  UNIQUE INDEX `sql_version`(`sql_version`, `id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_unicode_ci COMMENT = '用户各币种余额表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_amount
-- ----------------------------

-- ----------------------------
-- Table structure for user_apply_purchase_order
-- ----------------------------
DROP TABLE IF EXISTS `user_apply_purchase_order`;
CREATE TABLE `user_apply_purchase_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id\r\n',
  `order_code` varchar(100) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '订单编号',
  `user_id` bigint NULL DEFAULT NULL COMMENT '用户id',
  `apply_purchase_time` datetime(0) NULL DEFAULT NULL COMMENT '申购时间',
  `apply_purchase_amount` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '申购金额',
  `apply_purchase_quantity` int NULL DEFAULT 0 COMMENT '申购数量',
  `apply_purchase_single_amount` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '申购单价',
  `listing_start_date` datetime(0) NULL DEFAULT NULL COMMENT '上市开始日期',
  `winning_rate` decimal(22, 6) NULL DEFAULT NULL COMMENT '中签率',
  `winning_amount` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '中签金额',
  `winning_quantity` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '中签数量',
  `sell_price` decimal(22, 6) NULL DEFAULT NULL COMMENT '平仓价',
  `sell_time` datetime(0) NULL DEFAULT NULL COMMENT '平仓时间',
  `profit_and_lose` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '盈亏',
  `new_product_apply_purchase_id` bigint NULL DEFAULT NULL COMMENT '新股新币申购配置的id',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态：0：申购中 1：已上市',
  `product_type` tinyint(1) NULL DEFAULT 1 COMMENT '产品类型 1：股票 2：加密货币',
  `sql_version` bigint NULL DEFAULT 0 COMMENT 'sql版本',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_unicode_ci COMMENT = '用户新股新币申购订单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_apply_purchase_order
-- ----------------------------

-- ----------------------------
-- Table structure for user_bank
-- ----------------------------
DROP TABLE IF EXISTS `user_bank`;
CREATE TABLE `user_bank`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `user_id` bigint NOT NULL COMMENT '用户id',
  `bank_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '银行名称',
  `bank_no` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '银行卡号',
  `bank_open_address` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '开户行',
  `holder` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '开户人姓名',
  `bank_img` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行卡图片',
  `bank_phone` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '绑定手机号',
  `bank_country` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行国家',
  `aba_code` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'ABA代码',
  `swift` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'SWIFT',
  `post_code` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '邮编号码',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `user_real_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户地址',
  `account_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账户类型',
  `remark` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `user_id`(`user_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户银行卡' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_bank
-- ----------------------------

-- ----------------------------
-- Table structure for user_bill_detail
-- ----------------------------
DROP TABLE IF EXISTS `user_bill_detail`;
CREATE TABLE `user_bill_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `user_id` bigint NOT NULL COMMENT '用户id',
  `order_amount` decimal(22, 6) NOT NULL COMMENT '流水金额',
  `de_type` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '流水标题',
  `de_summary` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '流水内容',
  `order_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `amount_before` decimal(22, 6) NOT NULL COMMENT '变更前总资金',
  `amount_after` decimal(22, 6) NOT NULL COMMENT '变更后总资金',
  `relate_order_id` bigint NULL DEFAULT NULL COMMENT '相关订单id',
  `order_class` int NOT NULL COMMENT '订单类型：0：充值 1：提现  2：上分 3：下分 4：用户股票下单 5：用户股票平仓 6：用户加密货币下单\r\n7：用户加密货币平仓 8:极速交易下单  9：极速交易结算赢返还本金 10：下级返佣  11：资金互转扣除 12：资金互转收入 13：用户取消出金返还 14：提现驳回资金返还 15：极速交易结算获利 16:资金兑换手续费扣除\r\n17:理财产品购买扣除 18:理财产品日收益结算 19：理财产品本金退回 20:理财产品提前赎回违约金 21:新股申购下单扣除 22:申购未中签退回 23:现货交易下单扣除 24:现货交易卖出收入 25:用户期货下单 26：用户期货平仓 27：极速交易结算输返还本金  28：美股极速交易下单扣除 29：加密货币极速交易下单扣除 30：期货极速交易下单扣除  31：美股极速交易结算赢返还本金 32：加密货币极速交易结算赢返还本金 33：期货极速交易结算赢返还本金 34：美股极速交易结算获利 35：加密货币极速交易结算获利 36：期货极速交易结算获利 37：美股极速交易结算输返还本金 38：加密货币极速交易结算输返还本金 39：期货极速交易结算输返还本金 40:彩金赠送（系统充值）41：彩金赠送（福利彩金）42：彩金回收 43:用户外汇下单 44：用户外汇平仓 45:外汇极速交易结算赢返还本金 46：外汇极速交易结算获利 47：外汇极速交易结算输返还本金  48:外汇极速交易下单 49：股票极速交易结算平返还本金 50：加密货币极速交易结算平返还本金 51：期货极速交易结算平返还本金 52：外汇极速交易结算平返还本金 53：冻结资金 54：解冻资金 55：充值赠送彩金 56：注册赠送彩金 57：美股极速交易下单手续费扣除 58：加密货币极速交易下单手续费扣除 59：期货极速交易下单手续费扣除 60：外汇极速交易下单手续费扣除',
  `currency_id` bigint NOT NULL COMMENT '货币id',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `user_id`(`user_id`, `order_class`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户流水记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_bill_detail
-- ----------------------------

-- ----------------------------
-- Table structure for user_commission_record
-- ----------------------------
DROP TABLE IF EXISTS `user_commission_record`;
CREATE TABLE `user_commission_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `super_id` bigint NOT NULL COMMENT '上级id',
  `lower_id` bigint NOT NULL COMMENT '下级id',
  `commission_level` bigint NOT NULL COMMENT '返佣等级',
  `commission_amount` decimal(22, 6) NOT NULL COMMENT '返佣金额',
  `commission_profit` decimal(22, 6) NOT NULL COMMENT '返佣比例',
  `order_code_source` varchar(100) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '返佣的来源订单号',
  `order_code_commission` varchar(100) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '返佣的流水订单号',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '返佣时间',
  `currency_id` bigint NOT NULL DEFAULT 1 COMMENT '币种id',
  `commission_type` tinyint(1) NOT NULL COMMENT '返佣类型 0：充值',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `super_id`(`super_id`, `lower_id`, `create_time`, `currency_id`, `commission_type`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci COMMENT = '返佣记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_commission_record
-- ----------------------------

-- ----------------------------
-- Table structure for user_cryptocurrency_position
-- ----------------------------
DROP TABLE IF EXISTS `user_cryptocurrency_position`;
CREATE TABLE `user_cryptocurrency_position`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `order_code` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单号',
  `user_id` bigint NOT NULL COMMENT '用户id',
  `product_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '产品代码',
  `product_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '产品名称',
  `buy_order_time` datetime(0) NOT NULL COMMENT '购买时间',
  `buy_order_price` decimal(22, 6) NOT NULL COMMENT '购买价格',
  `sell_order_time` datetime(0) NULL DEFAULT NULL COMMENT '卖出时间',
  `sell_order_price` decimal(22, 6) NULL DEFAULT NULL COMMENT '卖出价格',
  `order_direction` tinyint(1) NOT NULL COMMENT '下单方向 0：买涨 1：买跌',
  `order_num` int NOT NULL COMMENT '订单数量',
  `order_lever` int NULL DEFAULT NULL COMMENT '杠杆倍数',
  `order_total_price` decimal(22, 6) NOT NULL COMMENT '订单买入花费',
  `order_fee` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '手续费',
  `order_yhs_fee` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '印花税',
  `profit_and_lose` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '浮动盈亏',
  `all_profit_and_lose` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '总盈亏',
  `is_lock` tinyint(1) NULL DEFAULT 0 COMMENT '是否锁仓 0：否 1：是',
  `lock_msg` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '锁仓原因',
  `currency_id` bigint NOT NULL DEFAULT 1 COMMENT '币种id',
  `stop_profit_price` decimal(22, 6) NULL DEFAULT NULL COMMENT '止盈线',
  `stop_loss_price` decimal(22, 6) NULL DEFAULT NULL COMMENT '止损线',
  `order_status` tinyint(1) NULL DEFAULT 0 COMMENT '订单状态：0：持仓中 1：已平仓',
  `sql_version` bigint NULL DEFAULT 0 COMMENT 'sql版本',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `order_code`(`order_code`) USING BTREE,
  UNIQUE INDEX `id`(`id`, `sql_version`) USING BTREE,
  INDEX `user_id`(`user_id`, `order_status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_unicode_ci COMMENT = '用户加密货币持仓' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_cryptocurrency_position
-- ----------------------------

-- ----------------------------
-- Table structure for user_fast_trade_control
-- ----------------------------
DROP TABLE IF EXISTS `user_fast_trade_control`;
CREATE TABLE `user_fast_trade_control`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `user_id` bigint NOT NULL COMMENT '用户id',
  `control_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '控制类型：0：全部未控 1：全部控赢 2：全部控输 3：注额概率控（全部） 4：注额概率控（买涨） 5：注额概率控（买跌） 6：账户余额概率控（全部）\r\n7：账户余额固定控（全部） 8：交易方向控（买多赢买空输） 9：交易方向控（买多输买空赢）\r\n',
  `min_limit_trade_amount` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '最小界限注额',
  `max_limit_trade_amount` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '最大界限注额',
  `win_percent_within_trade_amount` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '注额界限范围之内赢率',
  `win_percent_outside_trade_amount` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '注额界限范围之外赢率',
  `min_limit_user_balance` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '最小界限用户余额',
  `max_limit_user_balance` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '最大界限用户余额',
  `win_percent_within_user_balance` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '用户余额界限范围内赢率',
  `win_percent_outside_user_balance` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '用户余额界限范围之外赢率',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `user_id`(`user_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_unicode_ci COMMENT = '极速交易用户单控参数' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_fast_trade_control
-- ----------------------------

