  `buy_order_price` decimal(22, 6) NOT NULL COMMENT '购买价格',
  `sell_order_time` datetime(0) NULL DEFAULT NULL COMMENT '卖出时间',
  `sell_order_price` decimal(22, 6) NULL DEFAULT NULL COMMENT '卖出价格',
  `order_direction` tinyint(1) NOT NULL COMMENT '下单方向 0：买涨 1：买跌',
  `order_num` int NOT NULL COMMENT '订单数量',
  `order_lever` int NULL DEFAULT NULL COMMENT '杠杆倍数',
  `order_total_price` decimal(22, 6) NOT NULL COMMENT '订单买入花费',
  `order_fee` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '手续费',
  `order_yhs_fee` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '印花税',
  `profit_and_lose` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '浮动盈亏',
  `all_profit_and_lose` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '总盈亏',
  `is_lock` tinyint(1) NULL DEFAULT 0 COMMENT '是否锁仓 0：否 1：是',
  `lock_msg` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '锁仓原因',
  `currency_id` bigint NOT NULL DEFAULT 1 COMMENT '币种id',
  `stop_profit_price` decimal(22, 6) NULL DEFAULT NULL COMMENT '止盈线',
  `stop_loss_price` decimal(22, 6) NULL DEFAULT NULL COMMENT '止损线',
  `order_status` tinyint(1) NULL DEFAULT 0 COMMENT '订单状态：0：持仓中 1：已平仓',
  `sql_version` bigint NULL DEFAULT 0 COMMENT 'sql版本',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `order_code`(`order_code`) USING BTREE,
  UNIQUE INDEX `id`(`id`, `sql_version`) USING BTREE,
  INDEX `user_id`(`user_id`, `order_status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_unicode_ci COMMENT = '用户期货持仓' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_futures_position
-- ----------------------------

-- ----------------------------
-- Table structure for user_info
-- ----------------------------
DROP TABLE IF EXISTS `user_info`;
CREATE TABLE `user_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `user_account` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '用户账号',
  `phone` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '手机号',
  `email` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户邮箱',
  `nick_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '用户昵称',
  `real_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '真实名称',
  `user_pwd` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '登陆密码',
  `with_pwd` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '提现密码',
  `agent_id` bigint NULL DEFAULT NULL COMMENT '代理id',
  `agent_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '代理名称',
  `invite_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '邀请码',
  `account_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '账号类型： 0：真实用户 1：游客',
  `avatar` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户头像',
  `is_lock` tinyint(1) NULL DEFAULT 0 COMMENT '是否锁定 0：正常 1：锁定',
  `reg_time` datetime(0) NULL DEFAULT NULL COMMENT '注册时间',
  `reg_ip` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '注册ip',
  `reg_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '注册地址',
  `last_login_ip` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '最后登录ip',
  `last_login_time` datetime(0) NULL DEFAULT NULL COMMENT '最后登录时间',
  `id_card` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '身份证号码',
  `img1_key` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '证件图片（正面）',
  `img2_key` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '证件图片（背面）',
  `img3_key` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '证件图片（手持）',
  `is_active` tinyint(1) NULL DEFAULT 0 COMMENT '是否已实名 0：未实名 1：审核中 2：审核通过 3：审核驳回',
  `auth_method` tinyint(1) NULL DEFAULT 0 COMMENT '实名审核方式 0：身份证 1：驾驶证 2：护照',
  `auth_msg` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '实名审核反馈信息',
  `is_control` tinyint(1) NULL DEFAULT 0 COMMENT '0：正常 1：控制',
  `allow_fall_into_negative` tinyint(1) NULL DEFAULT 0 COMMENT '是否允许价格跌为负数 0：不允许 1：允许',
  `start_delay_time` int NULL DEFAULT 60 COMMENT '单控启动延时时间（单位：秒）',
  `overflow_amount` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '单控溢出数值',
  `sup_user_id` bigint NULL DEFAULT NULL COMMENT '上级用户id',
  `no_login_info` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '免登陆信息记录',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态 0：正常 1：禁用',
  `need_order_amount` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '打码量',
  `vip_level` int NULL DEFAULT 0 COMMENT 'vip等级',
  `credit_score` int NULL DEFAULT 100 COMMENT '信用分',
  `is_can_withdraw` tinyint(1) NULL DEFAULT 0 COMMENT '是否能提现：0：是 1：否',
  `fast_trade_win_profit_ratio` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '极速交易赢收益率',
  `fast_trade_lose_profit_ratio` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '极速交易输收益率',
  `is_agent` tinyint(1) NULL DEFAULT 0 COMMENT '是否设置为代理员 0：是 1：否',
  `is_del` tinyint(1) NULL DEFAULT 0 COMMENT '删除标志 0：未删除 1：已删除',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `invite_code`(`invite_code`) USING BTREE,
  INDEX `agent_id`(`agent_id`) USING BTREE,
  INDEX `sup_user_id`(`sup_user_id`) USING BTREE,
  INDEX `user_account`(`user_account`) USING BTREE,
  INDEX `phone`(`phone`) USING BTREE,
  INDEX `email`(`email`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 127 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户信息表' ROW_FORMAT = DYNAMIC;

