  `user_id` bigint NOT NULL COMMENT '用户id',
  `withdraw_amount` decimal(22, 6) NOT NULL COMMENT '提现金额',
  `apply_time` datetime(0) NOT NULL COMMENT '申请提现时间',
  `trans_time` datetime(0) NULL DEFAULT NULL COMMENT '审核时间',
  `operator_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '操作人名称',
  `receipt_account_info` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款账户信息',
  `wallet_receipt_qr_code` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '钱包收款码',
  `withdraw_status` tinyint(1) NULL DEFAULT 0 COMMENT '提现状态：0：审核中 1：审核通过 2：审核驳回 3：取消提现',
  `withdraw_fee` decimal(22, 6) NULL DEFAULT 0.000000 COMMENT '提现手续费',
  `withdraw_msg` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '返回信息',
  `currency_id` bigint NOT NULL DEFAULT 1 COMMENT '币种id',
  `withdraw_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '提现类型 0：银行卡 1：虚拟钱包',
  `user_amt_before` decimal(22, 6) NOT NULL COMMENT '余额变更前',
  `user_amt_after` decimal(22, 6) NOT NULL COMMENT '余额变更后',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `sql_version` bigint NULL DEFAULT 0 COMMENT 'sql版本',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `user_id`(`user_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '提现记录表' ROW_FORMAT = DYNAMIC;

